@extends('layouts.app') @section('title','Users') @section('heading','User Management') @section('subheading','Authorise staff and assign Admin, Manager or Staff access.') @section('actions')<button class="primary" onclick="document.getElementById('new-user').showModal()">+ Add user</button>@endsection @section('content')<section class="panel"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody>@foreach($users as $u)<tr><td><strong>{{ $u->name }}</strong></td><td>{{ $u->email }}</td><td colspan="4"><form class="user-row" method="post" action="{{ route('users.update',$u) }}">@csrf @method('patch')<select name="role"><option value="admin" @selected($u->role==='admin')>Admin</option><option value="manager" @selected($u->role==='manager')>Manager</option><option value="staff" @selected($u->role==='staff')>Staff</option></select><select name="is_active"><option value="1" @selected($u->is_active)>Active</option><option value="0" @selected(!$u->is_active)>Inactive</option></select><span>{{ $u->last_login_at?->format('d M Y H:i') ?? 'Never' }}</span><button>Save</button></form></td></tr>@endforeach</tbody></table></section><dialog id="new-user"><form class="entry-form" method="post" action="{{ route('users.store') }}">@csrf<div class="dialog-head"><h2>Authorise new user</h2><button type="button" onclick="this.closest('dialog').close()">×</button></div><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Role<select name="role"><option value="staff">Staff</option><option value="manager">Manager</option><option value="admin">Admin</option></select></label><div class="dialog-actions"><button type="button" onclick="this.closest('dialog').close()">Cancel</button><button class="primary">Add user</button></div></form></dialog>@endsection
